const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const master = JSON.parse(await fs.readFile(S+"\\_GIG_MASTER.json","utf8"));

// 生成 Netscape 书签格式（Chrome/Edge/Firefox 都能导入）
const esc = s => String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
const ts = Math.floor(Date.now()/1000);

const lines = [];
lines.push('<!DOCTYPE NETSCAPE-Bookmark-file-1>');
lines.push('<!-- This is an automatically generated file. It will be read and overwritten. DO NOT EDIT! -->');
lines.push('<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">');
lines.push('<TITLE>Bookmarks</TITLE>');
lines.push('<H1>Bookmarks</H1>');
lines.push('<DL><p>');
lines.push('    <DT><H3 ADD_DATE="'+ts+'" LAST_MODIFIED="'+ts+'">接单平台 70 个</H3>');
lines.push('    <DL><p>');

let idx = 0;
for (const [cat, items] of Object.entries(master.groups).sort((a,b)=>b[1].length-a[1].length)) {
  const cleanCat = cat.replace(/[🌍🧪🎓💰📝✍️🌐🤖💼📍🎨🇨🇳]/g,'').replace(/^\s*|\s*$/g,'').replace(/\s+/g,' ') || "其他";
  lines.push('        <DT><H3 ADD_DATE="'+ts+'" LAST_MODIFIED="'+ts+'">'+esc(cleanCat)+' ('+items.length+')</H3>');
  lines.push('        <DL><p>');
  for (const it of items) {
    const lvl = it.group==="能看到活" ? "[A]" : "[B]";
    const name = lvl + " " + it.name;
    const url = it.url || ("https://"+it.host);
    lines.push('            <DT><A HREF="'+esc(url)+'" ADD_DATE="'+ts+'">'+esc(name)+'</A>');
    idx++;
  }
  lines.push('        </DL><p>');
}
lines.push('    </DL><p>');
lines.push('</DL><p>');

await fs.writeFile(P2+"\\接单平台书签-70个.html", lines.join("\n"), "utf8");
const st = await fs.stat(P2+"\\接单平台书签-70个.html");
return { bytes: st.size, bookmarks: idx, categories: Object.keys(master.groups).length };
